package com.grifplot.libros;
import android.content.*;import android.graphics.*;import android.webkit.*;import android.widget.*;import android.view.*;import java.net.*;import java.io.*;
final class GoogleBrowser extends LinearLayout {
 final String originalQuery;LinearLayout top,tools;final MainActivity a;final WebView web;final EditText input;final CheckBox pdfOnly;final ProgressBar progress;final TextView location;volatile boolean closed=false;boolean downloading=false;
 GoogleBrowser(MainActivity act,String query){super(act);a=act;originalQuery=query;web=new WebView(a);setOrientation(VERTICAL);setBackgroundColor(MainActivity.BG);
 top=a.row();top.addView(a.button("‹ Biblioteca",v->a.results(),false));input=new EditText(a);input.setSingleLine(true);input.setTextSize(20);input.setHint("Busca en Google o escribe una URL");input.setText(query);top.addView(input,new LayoutParams(0,a.dp(56),1));top.addView(a.button("Buscar",v->search(),true));addView(top);
 tools=a.row();tools.addView(a.button("‹ Atrás",v->{if(web.canGoBack())web.goBack();},false));tools.addView(a.button("Recargar",v->web.reload(),false));pdfOnly=new CheckBox(a);pdfOnly.setText("Solo PDF");pdfOnly.setTextSize(17);pdfOnly.setChecked(true);tools.addView(pdfOnly);tools.addView(a.button("Abrir PDF del enlace",v->openPdf(web.getUrl(),web.getTitle()),false));tools.addView(a.button("Finalizar visita",v->a.finishVisit(),true));addView(tools);
 location=a.label("Google · "+query,14,MainActivity.MUTED);location.setSingleLine(true);location.setEllipsize(android.text.TextUtils.TruncateAt.END);addView(location);progress=new ProgressBar(a,null,android.R.attr.progressBarStyleHorizontal);progress.setMax(100);addView(progress,new LayoutParams(-1,a.dp(3)));
 WebSettings settings=web.getSettings();settings.setJavaScriptEnabled(true);settings.setDomStorageEnabled(true);settings.setAllowFileAccess(false);settings.setAllowContentAccess(false);settings.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);settings.setBuiltInZoomControls(true);settings.setDisplayZoomControls(false);settings.setSupportMultipleWindows(false);settings.setSafeBrowsingEnabled(true);android.webkit.CookieManager.getInstance().setAcceptThirdPartyCookies(web,false);web.setWebChromeClient(new WebChromeClient(){public void onProgressChanged(WebView v,int n){progress.setProgress(n);progress.setVisibility(n==100?GONE:VISIBLE);}});
 web.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){String url=r.getUrl().toString();if(!r.isForMainFrame())return false;if(BrowserRules.pdf(url)){openPdf(url,null);return true;}if(!BrowserRules.web(url)){a.toast("Este enlace no es una página web ni un PDF público");return true;}if(url.startsWith("http://")){v.loadUrl("https://"+url.substring(7));return true;}return false;}
 public void onPageStarted(WebView v,String url,Bitmap icon){location.setText(url);a.touch();if(BrowserRules.pdf(url))openPdf(url,null);}
 public void onReceivedError(WebView v,WebResourceRequest r,WebResourceError e){if(r.isForMainFrame()&&!downloading&&!closed)a.toast("No se pudo cargar la página. Revisa la conexión o pulsa Recargar.");}
 public void onReceivedSslError(WebView v,android.webkit.SslErrorHandler h,android.net.http.SslError error){h.cancel();a.toast("El enlace no tiene una conexión segura válida");}
 public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest r){if(!r.isForMainFrame()||closed||!BrowserRules.web(r.getUrl().toString()))return null;String url=r.getUrl().toString(),host=r.getUrl().getHost();if(host!=null&&(host.contains("google.")||host.equals("accounts.google.com")))return null;HttpURLConnection c=null;try{c=(HttpURLConnection)new URL(url).openConnection();c.setRequestMethod("HEAD");c.setConnectTimeout(4000);c.setReadTimeout(4000);c.setRequestProperty("User-Agent",WebSettings.getDefaultUserAgent(a));String cookie=android.webkit.CookieManager.getInstance().getCookie(url);if(cookie!=null)c.setRequestProperty("Cookie",cookie);c.connect();String type=c.getContentType();if(type!=null&&type.toLowerCase().contains("application/pdf")){a.ui.post(()->openPdf(url,null));return new WebResourceResponse("text/html","UTF-8",new ByteArrayInputStream("<html><body>Abriendo PDF en Grifplotlibros…</body></html>".getBytes("UTF-8")));}}catch(Exception ignored){}finally{if(c!=null)c.disconnect();}return null;}});
 web.setDownloadListener((url,ua,disposition,mime,length)->{if(BrowserRules.pdf(url)||URLUtil.guessFileName(url,disposition,mime).toLowerCase().endsWith(".pdf")||(mime!=null&&mime.toLowerCase().contains("pdf")))openPdf(url,URLUtil.guessFileName(url,disposition,mime));else a.message("Descarga no compatible","El lector abre archivos PDF. Elige un enlace PDF público de la fuente.");});addView(web,new LayoutParams(-1,0,1));LargeKeyboard.bind(a,input,()->search(),false);input.setImeOptions(android.view.inputmethod.EditorInfo.IME_ACTION_SEARCH);input.setOnEditorActionListener((v,action,event)->{search();return true;});web.loadUrl(BrowserRules.google(query,true));}
 void compact(boolean compact){top.setVisibility(compact?GONE:VISIBLE);tools.setVisibility(compact?GONE:VISIBLE);}
 void search(){String s=input.getText().toString().trim();if(s.isEmpty())return;downloading=false;a.query=s;((android.view.inputmethod.InputMethodManager)a.getSystemService(Context.INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(input.getWindowToken(),0);input.clearFocus();if(BrowserRules.web(s))web.loadUrl(s.startsWith("http://")?"https://"+s.substring(7):s);else web.loadUrl(BrowserRules.google(s,pdfOnly.isChecked()));}
 void openPdf(String url,String name){if(closed||downloading||!(a.screen.equals("browser")||a.screen.equals("results")))return;if(url==null||!BrowserRules.web(url)){a.toast("Abre primero un enlace web de un PDF");return;}downloading=true;web.stopLoading();String title=name==null||name.trim().isEmpty()?URLUtil.guessFileName(url,null,"application/pdf"):name;String ua=web.getSettings().getUserAgentString(),cookie=android.webkit.CookieManager.getInstance().getCookie(url),referer=web.getUrl();a.downloadWebPdf(url,title,ua,cookie,referer,()->downloading=false);}
 void close(){if(closed)return;closed=true;web.stopLoading();web.loadUrl("about:blank");web.clearHistory();web.clearFormData();web.clearCache(false);removeView(web);web.destroy();android.webkit.CookieManager.getInstance().removeAllCookies(null);WebStorage.getInstance().deleteAllData();}
}
